\":[\"Satire & parody\",\"Management, leadership & organizations\",\"Stand-up & sketch comedy\"],\"tags\":[\"david mitchell\",\"satire\",\"jobs\",\"recruiting\",\"work culture\"],\"quote\":\"David Mitchell had a very good take on it.\",\"recommenders\":2,\"score\":2.0},{\"vid\":\"C1KT8PS6Zs4\",\"title\":\"MOLTEN GLASS VS Prince Rupert's Drop - Smarter Every Day 285\",\"channel\":\"SmarterEveryDay\",\"summary\":\"Destin Sandlin of Smarter Every Day explores molten glass and Prince Rupert's drops with a glass artist, including a process that freezes the moment glass shatters and an artisan who makes the drops.\",\"why_hn\":\"Commenters recommend it for the striking glass-shattering visuals and the artist's attitude of treating failure as a space for discovery.\",\"content_type\":\"explainer\",\"level\":\"general\",\"primary_topic\":\"glass physics\",\"categories\":[\"Everyday physics & science demos\",\"Materials science\"],\"tags\":[\"prince rupert's drop\",\"molten glass\",\"glass art\",\"materials science\",\"smarter every day\"],\"quote\":\"Learn about and see how it’s made\",\"recommenders\":2,\"score\":2.0},{\"vid\":\"CD0y-aU1sXo\",\"title\":\"Agile Project Management with Kanban | Eric Brechner | Talks at Google\",\"channel\":\"Talks at Google\",\"summary\":\"Eric Brechner, a Microsoft Xbox development manager, presents his Kanban approach for agile project management at Talks at Google. He covers using sticky notes to organize work, estimate and meet deadlines.\",\"why_hn\":\"Recommended as a clear description of how Kanban works and a practical alternative to sprints.\",\"content_type\":\"talk\",\"level\":\"intro\",\"primary_topic\":\"kanban project management\",\"categories\":[\"Software practice, open source & careers\",\"Management, leadership & organizations\"],\"tags\":[\"kanban\",\"agile\",\"project management\",\"eric brechner\",\"sprints\"],\"quote\":\"Eric Brechner of Microsoft (of all possible places...) gives a great talk on his team's approach\",\